using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AEPolish {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/F1_AbandonedCamouflage/";static string O=>R+"/Docs/Review/2026-11-12_1F_Abandoned/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var root=GameObject.Find("1F_AbandonedFactory");var old=JObject.Parse(File.ReadAllText(O+"apply.json"));var names=old["replaced"].Concat(old["removed"]).Select(v=>(string)v).ToHashSet();var all=root.GetComponentsInChildren<Transform>(true);var deleted=new List<string>();foreach(var tr in all){if(!tr)continue;if((names.Contains(tr.name)&&!tr.gameObject.activeSelf)||((tr.name.StartsWith("C01_TaskLight")||tr.name.StartsWith("C02_TaskLight"))&&tr.name.EndsWith("_Fixture"))){deleted.Add(tr.name);UnityEngine.Object.DestroyImmediate(tr.gameObject);}}
  // Keep terrain beneath exterior wall edges so low views cannot see through heightmap-hole stair steps.
  var td=root.GetComponentInChildren<Terrain>().terrainData;int n=td.heightmapResolution,ar=td.alphamapResolution;using(var br=new BinaryReader(File.OpenRead(H+"terrain.bin"))){if(br.ReadInt32()!=n||br.ReadInt32()!=ar)throw new Exception("Terrain mismatch");br.BaseStream.Seek((long)n*n*4+(long)ar*ar*3*4,SeekOrigin.Current);var holes=new bool[n-1,n-1];for(int z=0;z<n-1;z++)for(int x=0;x<n-1;x++)holes[z,x]=br.ReadByte()!=0;td.SetHoles(0,0,holes);}EditorUtility.SetDirty(td);
  // Large trees have trunk collision while leaves and grass remain non-blocking.
  var parent=root.transform.Find("AbandonedCamouflage/OvergrownSite");if(!parent.Find("TreeTrunks")){var g=new GameObject("TreeTrunks");g.transform.SetParent(parent,false);var t=root.GetComponentInChildren<Terrain>();foreach(var a in new[]{new Vector3(-56,5.5f,40),new Vector3(-64,6.7f,36),new Vector3(-72,5,19),new Vector3(-63,4.5f,-43),new Vector3(-25,6.1f,60),new Vector3(0,5.6f,57),new Vector3(21,6.7f,48),new Vector3(36,5.4f,59),new Vector3(58,6.7f,9),new Vector3(69,5.5f,0),new Vector3(59,6.3f,-34),new Vector3(45,5.4f,-50)}){var c=g.AddComponent<CapsuleCollider>();float y=t.SampleHeight(new Vector3(a.x,0,a.z))+t.transform.position.y;c.center=new Vector3(a.x,y+a.y*.5f,a.z);c.height=a.y;c.radius=.14f;}}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);EditorSceneManager.OpenScene(s.path);File.WriteAllText(O+"polish.json",JsonConvert.SerializeObject(new{obsoleteSceneObjectsRemoved=deleted.Count,deleted,terrainEdgePatched=true,treeColliders=12},Formatting.Indented));return new{removed=deleted.Count,saved=true};
 }
}
